@startuml

class GasStation {
  + Address : string
}

class Pump {
  + CurrentLevel : float
  + ReorderingLevel : float
  + CriticalLevel : float
  + IsBlocked : boolean
}

class Reservoir {
  + Quantity : float
}

class RefuelTurn {
  + StartTime : time
  + EndTime : time
  + Quantity : float
}

class Customer {
  + Name : string
  + IsSuspended : boolean
}

class RefuelCard {
  + CardNumber : string
  + IsBlocked : boolean
}

class Invoice {
  + Month : int
  + Year : int
  + Discount : float
}

class Payment {
  + Date : date
  + Amount : double
}

GasStation "1" *-- "*" Pump
Pump "1" *-- "1" Reservoir
Pump "1" -- "*" RefuelTurn
Customer "0..1" -- "0..*" RefuelTurn : pays for
Customer "1" -- "0..1" RefuelCard : owns
RefuelCard "1" -- "0..*" RefuelTurn : used for
Invoice "1" -- "1..*" RefuelTurn : contains
Invoice "1" -- "0..*" Payment : settled by

@enduml

